(function () {
"use strict";
if (window.__hotboardInjected) return;
window.__hotboardInjected = true;
var me = document.currentScript || document.querySelector('script[src*="hotboard-inject"]');
function attr(n, d) { return (me && me.getAttribute(n)) || d; }
var base = window.HOTBOARD_BASE || attr("data-base", "/hotboard/");
if (base.charAt(base.length - 1) !== "/") base += "/";
var anchorSel = window.HOTBOARD_ANCHOR || attr("data-anchor", "#searchInput");
var closestSel = window.HOTBOARD_ANCHOR_CLOSEST !== undefined
? window.HOTBOARD_ANCHOR_CLOSEST : attr("data-anchor-closest", "section");
var version = window.HOTBOARD_ASSET_VERSION || attr("data-version", "20261111c");
function load(src) {
return new Promise(function (resolve, reject) {
var s = document.createElement("script");
s.src = src + "?v=" + encodeURIComponent(version);
s.async = false;
s.onload = resolve;
s.onerror = function () { reject(new Error("load failed: " + src)); };
document.head.appendChild(s);
});
}
function tryMount() {
if (!window.HotBoardEmbed) return;
var anchor = document.querySelector(anchorSel);
if (!anchor) return;                       // SSR 尚未输出搜索区，等下一次 DOM 变化
if (closestSel && anchor.closest) anchor = anchor.closest(closestSel) || anchor;
if (!anchor || !anchor.parentNode) return;
if (window.HotBoardEmbed.isMounted()) return;
window.HotBoardEmbed.mount({ anchor: anchor, placement: "after", base: base });
}
function start() {
var chain = Promise.resolve();
if (!window.HotBoardConfig) {
chain = chain.then(function () { return load(base + "assets/config.js"); });
}
chain = chain.then(function () {
if (!window.HotBoard) return load(base + "assets/sources.js");
});
chain = chain.then(function () {
var prod = window.HotBoardConfig && window.HotBoardConfig.PRODUCTION;
if (!prod && !window.HOTBOARD_SAMPLE) return load(base + "assets/sample.js");
});
chain = chain.then(function () {
if (!window.HotBoardEmbed) return load(base + "assets/embed.js");
});
chain.then(function () {
tryMount();
var mo = new MutationObserver(tryMount);
mo.observe(document.documentElement || document.body, { childList: true, subtree: true });
setTimeout(tryMount, 1500);
}).catch(function (e) {
console.warn("[HotBoard] 注入失败，主站不受影响：", e);
});
}
if (document.readyState === "loading") {
document.addEventListener("DOMContentLoaded", start);
} else {
start();
}
})();
